examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space3) {
    MonarchTermsAcceptance(isAccepted: $accepted, documents: documents)
    MonarchButton({{submit}}, variant: .primary) {}
}

examples.setupTemplate:
@State private var accepted = false
private let documents = [
    MonarchTermsDocument({{documents.0.label}}, url: URL(filePath: "/terms"), version: {{documents.0.version}}),
    MonarchTermsDocument({{documents.1.label}}, url: URL(filePath: "/privacy"), version: {{documents.1.version}}),
]

examples.setup:
